CREATE TABLE department (id varchar(64) PRIMARY KEY, name text NOT NULL, parent_id varchar(64) REFERENCES department(id), CHECK (id <> parent_id));
CREATE TABLE goal (id varchar(64) PRIMARY KEY, unit_id varchar(64) NOT NULL REFERENCES department(id), title text NOT NULL, owner text, parent_goal_id varchar(64) REFERENCES goal(id), status varchar(16) NOT NULL CHECK (status IN ('DRAFT','ACTIVE','COMPLETED','CANCELLED')), due_date date, CHECK (id <> parent_goal_id));
CREATE TABLE key_result (id varchar(64) PRIMARY KEY, goal_id varchar(64) NOT NULL REFERENCES goal(id), title text NOT NULL, target_value numeric(19,4), actual_value numeric(19,4), weight numeric(7,4) NOT NULL CHECK (weight BETWEEN 0 AND 100), fact_updated_on date);
CREATE TABLE quality_rule (code varchar(64) PRIMARY KEY, title text NOT NULL, severity varchar(16) NOT NULL CHECK (severity IN ('critical','major','minor')), description text NOT NULL);
CREATE TABLE quality_run (id varchar(64) PRIMARY KEY, snapshot_date date NOT NULL, compared_to_run_id varchar(64) REFERENCES quality_run(id), status varchar(16) NOT NULL CHECK (status IN ('RUNNING','COMPLETED','FAILED')), rule_set_version varchar(16) NOT NULL DEFAULT 'v1', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, failure_code text, CHECK (id <> compared_to_run_id));
CREATE TABLE run_department (run_id varchar(64) NOT NULL REFERENCES quality_run(id), unit_id varchar(64) NOT NULL, name text NOT NULL, parent_unit_id varchar(64), PRIMARY KEY (run_id, unit_id), FOREIGN KEY (run_id,parent_unit_id) REFERENCES run_department(run_id,unit_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE run_goal (run_id varchar(64) NOT NULL REFERENCES quality_run(id), goal_id varchar(64) NOT NULL, unit_id varchar(64) NOT NULL, title text NOT NULL, owner text, parent_goal_id varchar(64), status varchar(16) NOT NULL CHECK (status IN ('DRAFT','ACTIVE','COMPLETED','CANCELLED')), due_date date, PRIMARY KEY (run_id,goal_id), FOREIGN KEY (run_id,unit_id) REFERENCES run_department(run_id,unit_id), FOREIGN KEY (run_id,parent_goal_id) REFERENCES run_goal(run_id,goal_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE run_key_result (run_id varchar(64) NOT NULL REFERENCES quality_run(id), kr_id varchar(64) NOT NULL, goal_id varchar(64) NOT NULL, title text NOT NULL, target_value numeric(19,4), actual_value numeric(19,4), weight numeric(7,4) NOT NULL CHECK (weight BETWEEN 0 AND 100), fact_updated_on date, PRIMARY KEY (run_id,kr_id), UNIQUE (run_id,kr_id,goal_id), FOREIGN KEY (run_id,goal_id) REFERENCES run_goal(run_id,goal_id));
CREATE TABLE quality_issue (id uuid PRIMARY KEY, run_id varchar(64) NOT NULL REFERENCES quality_run(id), rule_code varchar(64) NOT NULL REFERENCES quality_rule(code), object_type varchar(8) NOT NULL CHECK (object_type IN ('goal','kr')), object_id varchar(64) NOT NULL, goal_id varchar(64) NOT NULL, kr_id varchar(64), severity varchar(16) NOT NULL CHECK (severity IN ('critical','major','minor')), message text NOT NULL, details jsonb NOT NULL, UNIQUE (run_id,rule_code,object_type,object_id), FOREIGN KEY (run_id,goal_id) REFERENCES run_goal(run_id,goal_id), FOREIGN KEY (run_id,kr_id,goal_id) REFERENCES run_key_result(run_id,kr_id,goal_id), CHECK ((object_type='goal' AND object_id=goal_id AND kr_id IS NULL) OR (object_type='kr' AND kr_id IS NOT NULL AND object_id=kr_id)));
CREATE INDEX department_parent_idx ON department(parent_id);
CREATE INDEX goal_unit_idx ON goal(unit_id);
CREATE INDEX goal_parent_idx ON goal(parent_goal_id);
CREATE INDEX kr_goal_idx ON key_result(goal_id);
CREATE INDEX run_department_parent_idx ON run_department(run_id,parent_unit_id);
CREATE INDEX run_goal_unit_idx ON run_goal(run_id,unit_id);
CREATE INDEX run_goal_parent_idx ON run_goal(run_id,parent_goal_id);
CREATE INDEX run_kr_goal_idx ON run_key_result(run_id,goal_id);
CREATE INDEX issue_filters_idx ON quality_issue(run_id,rule_code,severity);
CREATE INDEX issue_goal_idx ON quality_issue(run_id,goal_id);
CREATE INDEX run_date_idx ON quality_run(snapshot_date,id);
